    const fs = require("fs");

    const path = require("path");
    const src = fs.readFileSync(path.resolve(__dirname, "PullToRefresh.tsx"), "utf8");
    expect(src).toMatch(/ACTIVATION_THRESHOLD\s*=\s*100\b/);
    expect(src).toMatch(/window\.scrollY\s*===\s*0/);
