import React, { useState, useEffect, useCallback, useRef } from 'react';

interface SplitPaneProps {
  /** The sidebar content (e.g., navigation) */
  sidebar: React.ReactNode;
  /** The main content area (e.g., data tables, forms) */
  mainContent: React.ReactNode;
  /** Minimum width of the sidebar in pixels */
  minSidebarWidth?: number;
  /** Maximum width of the sidebar in pixels (optional) */
  maxSidebarWidth?: number;
  /** Default width of the sidebar in pixels */
  defaultSidebarWidth?: number;
  /** LocalStorage key to persist the sidebar width */
  storageKey?: string;
}

/**
 * SplitPane Component
 * 
 * Provides a draggable vertical divider between a sidebar and main content area.
 * 
 * Key Features:
 * - Persists user preference in localStorage.
 * - Enforces min/max width constraints.
 * - CRITICAL: Applies `pointer-events: none` to the main content area during 
 *   dragging to prevent iframe mouse event trapping (a common browser bug where 
 *   mousemove events stop firing when the cursor enters an iframe).
 */
export const SplitPane: React.FC<SplitPaneProps> = ({
  sidebar,
  mainContent,
  minSidebarWidth = 200,
  maxSidebarWidth = 600,
  defaultSidebarWidth = 280,
  storageKey = 'campusconnect-admin-sidebar-width',
}) => {
  // Initialize width from localStorage or fallback to default
  const [sidebarWidth, setSidebarWidth] = useState<number>(() => {
    if (typeof window !== 'undefined') {
      const stored = localStorage.getItem(storageKey);
      if (stored) {
        const parsed = parseInt(stored, 10);
        // Ensure stored value is within bounds
        return Math.max(minSidebarWidth, Math.min(maxSidebarWidth, parsed));
      }
    }
    return defaultSidebarWidth;
  });

  const [isDragging, setIsDragging] = useState(false);
  const startXRef = useRef(0);
  const startWidthRef = useRef(0);

  // Persist width to localStorage whenever it changes and is valid
  useEffect(() => {
    if (typeof window !== 'undefined') {
      localStorage.setItem(storageKey, sidebarWidth.toString());
    }
  }, [sidebarWidth, storageKey]);

  // Handle mouse down on the resizer
  const handleMouseDown = useCallback(
    (e: React.MouseEvent) => {
      e.preventDefault();
      setIsDragging(true);
      startXRef.current = e.clientX;
      startWidthRef.current = sidebarWidth;
    },
    [sidebarWidth]
  );

  // Handle global mouse move while dragging
  useEffect(() => {
    if (!isDragging) return;

    const handleMouseMove = (e: MouseEvent) => {
      const delta = e.clientX - startXRef.current;
      let newWidth = startWidthRef.current + delta;

      // Enforce constraints
      newWidth = Math.max(minSidebarWidth, Math.min(maxSidebarWidth, newWidth));

      setSidebarWidth(newWidth);
    };

    const handleMouseUp = () => {
      setIsDragging(false);
    };

    // Attach listeners to window to ensure we catch events even if mouse moves fast
    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);

    // Cleanup listeners on unmount or when dragging stops
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isDragging, minSidebarWidth, maxSidebarWidth]);

  // Prevent text selection while dragging
  useEffect(() => {
    if (isDragging) {
      document.body.style.userSelect = 'none';
      document.body.style.cursor = 'col-resize';
    } else {
      document.body.style.userSelect = '';
      document.body.style.cursor = '';
    }
    return () => {
      document.body.style.userSelect = '';
      document.body.style.cursor = '';
    };
  }, [isDragging]);

  return (
    <div className="flex h-full w-full overflow-hidden">
      {/* Sidebar Area */}
      <aside 
        className="flex-shrink-0 bg-background border-r border-border transition-none"
        style={{ width: `${sidebarWidth}px` }}
      >
        {sidebar}
      </aside>

      {/* Resizer Handle */}
      <div
        className={`resizer cursor-col-resize w-1 bg-border hover:bg-primary/50 active:bg-primary transition-colors flex-shrink-0 relative z-10 ${
          isDragging ? 'bg-primary' : ''
        }`}
        onMouseDown={handleMouseDown}
        role="separator"
        aria-valuenow={sidebarWidth}
        aria-valuemin={minSidebarWidth}
        aria-valuemax={maxSidebarWidth}
        aria-label="Resize sidebar"
        tabIndex={0}
      >
        {/* Visual grip indicator */}
        <div className="absolute inset-y-0 left-1/2 -translate-x-1/2 w-4 flex items-center justify-center">
          <div className="h-8 w-1 bg-muted-foreground/30 rounded-full" />
        </div
      </div>

      {/* Main Content Area */}
      <main 
        className="flex-1 overflow-auto bg-background relative"
        // CRITICAL FIX: Disable pointer events on main content while dragging 
        // to prevent iframe from stealing mousemove events.
        style={{ pointerEvents: isDragging ? 'none' : 'auto' }}
      >
        {mainContent}
      </main>
    </div>
  );
};

export default SplitPane;

import React, { createContext, useContext, useEffect, useState, ReactNode } from "react";
import { SessionManager } from "@/lib/SessionManager";
import { createClient } from "@/lib/supabase/client";
import { toast } from "sonner";

interface AuthSecurityContextType {
  isAuthenticated: boolean;
  token: string | null;
  isLeaderTab: boolean;
  mfaVerified: boolean;
  sessionTimeoutWarning: boolean;
  triggerLogout: () => void;
  verifyMfaSession: () => void;
  extendSession: () => void;
}

const AuthSecurityContext = createContext<AuthSecurityContextType | undefined>(undefined);

export const AuthSecurityProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(true);
  const [token, setToken] = useState<string | null>(null);
  const [isLeaderTab, setIsLeaderTab] = useState<boolean>(false);
  const [mfaVerified, setMfaVerified] = useState<boolean>(true);
  const [sessionTimeoutWarning, setSessionTimeoutWarning] = useState<boolean>(false);

  const supabase = createClient();

  useEffect(() => {
    const sessionManager = SessionManager.getInstance();
    setIsLeaderTab(sessionManager.isLeader);

    const handleLogout = () => {
      setIsAuthenticated(false);
      setToken(null);
      toast.info("Session expired or signed out from another tab.");
    };

    const handleTokenUpdate = (newToken: string) => {
      setToken(newToken);
      setIsAuthenticated(true);
    };

    sessionManager.setCallbacks(handleLogout, handleTokenUpdate);

    // Initial auth check with Supabase
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session) {
        setIsAuthenticated(true);
        setToken(session.access_token);
      }
    });

    // Listen for auth state changes
    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session) {
        setIsAuthenticated(true);
        setToken(session.access_token);
      } else {
        setIsAuthenticated(false);
        setToken(null);
      }
    });

    return () => {
      subscription.unsubscribe();
    };
  }, []);

  const triggerLogout = () => {
    const sessionManager = SessionManager.getInstance();
    sessionManager.broadcastLogout();
    supabase.auth.signOut().then(() => {
      setIsAuthenticated(false);
      setToken(null);
      window.location.href = "/auth";
    });
  };

  const verifyMfaSession = () => {
    setMfaVerified(true);
  };

  const extendSession = () => {
    setSessionTimeoutWarning(false);
    toast.success("Session successfully extended!");
  };

  return (
    <AuthSecurityContext.Provider
      value={{
        isAuthenticated,
        token,
        isLeaderTab,
        mfaVerified,
        sessionTimeoutWarning,
        triggerLogout,
        verifyMfaSession,
        extendSession,
      }}
    >
      {children}
    </AuthSecurityContext.Provider>
  );
};

export const useAuthSecurity = () => {
  const context = useContext(AuthSecurityContext);
  if (!context) {
    throw new Error("useAuthSecurity must be used within an AuthSecurityProvider");
  }
  return context;
};

import React, { useEffect, useState, useRef, useCallback } from "react";
import { List, ChevronDown, AlignLeft, ArrowUpRight } from "lucide-react";
import { cn } from "@/lib/utils";

export interface HeadingItem {
  id: string;
  text: string;
  level: number; // 2 for h2, 3 for h3
}

export interface DocumentScrollSpyProps {
  /** Array of headings or container selector to observe */
  headings?: HeadingItem[];
  /** Container ref/selector where the markdown content resides */
  contentContainerRef?: React.RefObject<HTMLElement | null>;
  /** Optional title for the Table of Contents card */
  title?: string;
  /** Additional CSS class names */
  className?: string;
}

/**
 * Extracts <h2> and <h3> heading elements from a DOM element container.
 */
export function extractHeadingsFromDOM(container: HTMLElement): HeadingItem[] {
  const elements = Array.from(container.querySelectorAll("h2, h3"));
  return elements.map((el, index) => {
    if (!el.id) {
      el.id = `heading-section-${index}-${el.textContent?.toLowerCase().replace(/\W+/g, "-") || "sec"}`;
    }
    return {
      id: el.id,
      text: el.textContent || `Section ${index + 1}`,
      level: el.tagName.toLowerCase() === "h2" ? 2 : 3,
    };
  });
}

/**
 * Dynamic Table of Contents (Scroll Spy) component (#1969).
 * Observes document headings using IntersectionObserver and mathematically determines
 * the heading closest to the top of the viewport to set active reading state.
 */
export const DocumentScrollSpy: React.FC<DocumentScrollSpyProps> = ({
  headings: initialHeadings,
  contentContainerRef,
  title = "Table of Contents",
  className = "",
}) => {
  const [headings, setHeadings] = useState<HeadingItem[]>(initialHeadings || []);
  const [activeId, setActiveId] = useState<string>("");
  const [isMobileOpen, setIsMobileOpen] = useState(false);
  const observerRef = useRef<IntersectionObserver | null>(null);

  // Parse headings from DOM if contentContainerRef is passed
  useEffect(() => {
    if (contentContainerRef?.current) {
      const extracted = extractHeadingsFromDOM(contentContainerRef.current);
      setHeadings(extracted);
      if (extracted.length > 0) setActiveId(extracted[0].id);
    } else if (initialHeadings && initialHeadings.length > 0) {
      setHeadings(initialHeadings);
      setActiveId(initialHeadings[0].id);
    }
  }, [contentContainerRef, initialHeadings]);

  // Set up IntersectionObserver with scroll proximity math for short sections
  useEffect(() => {
    if (headings.length === 0) return;

    const visibleElements = new Map<string, number>();

    const handleIntersect: IntersectionObserverCallback = (entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          visibleElements.set(entry.target.id, entry.boundingClientRect.top);
        } else {
          visibleElements.delete(entry.target.id);
        }
      });

      if (visibleElements.size > 0) {
        // Find section closest to top 20% of screen
        let closestId = "";
        let minDistance = Infinity;

        visibleElements.forEach((top, id) => {
          const distance = Math.abs(top - window.innerHeight * 0.15);
          if (distance < minDistance) {
            minDistance = distance;
            closestId = id;
          }
        });

        if (closestId) setActiveId(closestId);
      }
    };

    observerRef.current = new IntersectionObserver(handleIntersect, {
      rootMargin: "-10% 0px -70% 0px",
      threshold: [0, 0.25, 0.5, 1.0],
    });

    headings.forEach(({ id }) => {
      const el = document.getElementById(id);
      if (el) observerRef.current?.observe(el);
    });

    return () => {
      observerRef.current?.disconnect();
    };
  }, [headings]);

  const scrollToHeading = useCallback((id: string) => {
    const element = document.getElementById(id);
    if (element) {
      element.scrollIntoView({ behavior: "smooth", block: "start" });
      setActiveId(id);
      setIsMobileOpen(false);
    }
  }, []);

  if (headings.length === 0) return null;

  return (
    <div className={cn("w-full lg:w-64 shrink-0", className)}>
      {/* Mobile Collapsible Dropdown */}
      <div className="block lg:hidden mb-4 border-2 border-black bg-cream dark:border-cream dark:bg-black rounded-lg p-3">
        <button
          type="button"
          onClick={() => setIsMobileOpen((prev) => !prev)}
          className="flex w-full items-center justify-between font-mono text-xs font-bold uppercase text-black dark:text-cream"
        >
          <span className="flex items-center gap-2">
            <AlignLeft className="h-4 w-4 text-blue-600" /> {title}
          </span>
          <ChevronDown
            className={cn("h-4 w-4 transition-transform", isMobileOpen && "rotate-180")}
          />
        </button>

        {isMobileOpen && (
          <div className="mt-3 space-y-1.5 border-t border-black/20 pt-2.5 dark:border-white/20 font-mono text-xs">
            {headings.map((h) => (
              <button
                key={h.id}
                type="button"
                onClick={() => scrollToHeading(h.id)}
                className={cn(
                  "block w-full text-left py-1 px-2 rounded transition-colors truncate",
                  h.level === 3 ? "pl-5 text-[11px]" : "font-semibold",
                  activeId === h.id
                    ? "bg-lime text-black font-bold"
                    : "hover:bg-black/10 dark:hover:bg-white/10 text-neutral-700 dark:text-neutral-300",
                )}
              >
                {h.text}
              </button>
            ))}
          </div>
        )}
      </div>

      {/* Desktop Sticky Sidebar */}
      <nav
        aria-label="Table of Contents"
        className="hidden lg:block sticky top-24 rounded-xl border-2 border-black bg-cream p-4 dark:border-cream dark:bg-black shadow-md"
      >
        <div className="flex items-center gap-2 border-b-2 border-black pb-2.5 mb-3 dark:border-cream">
          <List className="h-4 w-4 text-blue-600" />
          <h4 className="font-display text-xs font-bold uppercase tracking-wider text-black dark:text-cream">
            {title}
          </h4>
        </div>

        <div className="space-y-1 font-mono text-xs max-h-[calc(100vh-160px)] overflow-y-auto pr-1">
          {headings.map((h) => {
            const isActive = activeId === h.id;
            return (
              <button
                key={h.id}
                type="button"
                onClick={() => scrollToHeading(h.id)}
                className={cn(
                  "flex w-full items-center justify-between rounded px-2.5 py-1.5 text-left transition-all duration-200",
                  h.level === 3 ? "pl-6 text-[11px]" : "font-semibold",
                  isActive
                    ? "bg-lime text-black font-bold border-l-4 border-black dark:border-white translate-x-1"
                    : "text-neutral-600 hover:text-black dark:text-neutral-400 dark:hover:text-white hover:bg-black/5 dark:hover:bg-white/5",
                )}
              >
                <span className="truncate">{h.text}</span>
                {isActive && <ArrowUpRight className="h-3 w-3 shrink-0 ml-1" />}
              </button>
            );
          })}
        </div>
      </nav>
    </div>
  );
};

import { createContext, useCallback, useContext, useMemo, useState, type ReactNode } from "react";
import type {
  ModalContextValue,
  ModalKind,
  ModalPropsByKind,
  ModalState,
} from "./ModalContext.types";

const ModalContext = createContext<ModalContextValue | null>(null);

export interface ModalProviderProps {
  children: ReactNode;
}

/**
 * ModalProvider ΓÇö owns the single piece of modal state for the whole
 * app (issue #1916).
 *
 * State shape mirrors the issue spec exactly:
 *   { activeModal: string | null, modalProps: any }
 *
 * `openModal(kind, props)` replaces any currently-active modal so
 * callers can't end up with two overlays stacked on top of each
 * other (the bug the issue calls out: "If a user clicks Login, then
 * clicks a background Filter button, both modals open simultaneously,
 * fighting for Z-index supremacy").
 */
export function ModalProvider({ children }: ModalProviderProps) {
  const [state, setState] = useState<ModalState>({
    activeModal: null,
    modalProps: undefined,
  });

  const openModal = useCallback(<K extends ModalKind>(kind: K, props?: ModalPropsByKind[K]) => {
    setState({ activeModal: kind, modalProps: props });
  }, []);

  const closeModal = useCallback(() => {
    setState({ activeModal: null, modalProps: undefined });
  }, []);

  const isOpen = useCallback((kind: ModalKind) => state.activeModal === kind, [state.activeModal]);

  const value = useMemo<ModalContextValue>(
    () => ({
      activeModal: state.activeModal,
      modalProps: state.modalProps,
      openModal,
      closeModal,
      isOpen,
    }),
    [state.activeModal, state.modalProps, openModal, closeModal, isOpen],
  );

  return <ModalContext.Provider value={value}>{children}</ModalContext.Provider>;
}

/**
 * useModal ΓÇö the consumer hook for the unified modal context.
 *
 * Throws if used outside a <ModalProvider>, so consumers get a
 * clear error message instead of silent undefined behavior.
 */
export function useModal(): ModalContextValue {
  const ctx = useContext(ModalContext);
  if (!ctx) {
    throw new Error("useModal must be used within a <ModalProvider>");
  }
  return ctx;
}

/**
 * useOptionalModal ΓÇö like useModal, but returns `null` when the
 * component tree has no <ModalProvider>.
 *
 * For components (e.g. global overlays mounted in <Layout>) that
 * must work both with and without the provider, this avoids the
 * throw above without restructuring their placement.
 */
export function useOptionalModal(): ModalContextValue | null {
  return useContext(ModalContext);
}

import { useModal } from "./ModalContext";
import type { ModalKind } from "./ModalContext.types";
import type { ComponentType, ReactNode } from "react";

/**
 * A registration entry in <ModalRoot />: maps a ModalKind to the
 * React component that should render for it, plus a small wrapper
 * that bridges the modalProps the context holds to the props the
 * component actually expects.
 */
export interface ModalRegistration<K extends ModalKind> {
  /**
   * Pure renderer that takes the active modal's props and returns
   * the React node to mount. Returning null means "don't render
   * anything for this kind right now" ΓÇö useful for modals that
   * defer until something is ready.
   */
  render: (props: unknown) => ReactNode;
}

/**
 * Map of ModalKind -> registration. Concrete modals register
 * themselves by extending this map at the call site of
 * <ModalRoot registrations={...} />.
 */
export type ModalRegistrationMap = {
  [K in ModalKind]?: ModalRegistration<K>;
};

interface ModalRootProps {
  registrations: ModalRegistrationMap;
}

/**
 * ModalRoot ΓÇö the global modal renderer (issue #1916 step 2/3).
 *
 * Sits at the top of App.tsx and listens to the modal context. When
 * `activeModal` is set, it looks up the registration and mounts the
 * matching component, passing it the modalProps from the context.
 *
 * Closing the modal (via the registered closeOn prop, a backdrop
 * click, or Escape) calls `closeModal()` from the context. Closing
 * unmounts the child entirely, wiping its internal state cleanly ΓÇö
 * which is what the issue asks for at the end of step 5.
 */
export function ModalRoot({ registrations }: ModalRootProps) {
  const { activeModal, modalProps, closeModal } = useModal();

  if (!activeModal) return null;

  const registration = registrations[activeModal];
  if (!registration) {
    // A kind is active but no one registered a renderer for it.
    // That's a developer error; surface a clear console message so
    // it's easy to debug without crashing the app.
    if (typeof console !== "undefined") {
      console.warn(`[ModalRoot] No registration for kind "${activeModal}"`);
    }
    return null;
  }

  const node = registration.render(modalProps);

  return (
    <div
      data-testid="modal-root"
      data-active-modal={activeModal}
      onKeyDown={(e) => {
        if (e.key === "Escape") closeModal();
      }}
    >
      {node}
    </div>
  );
}

/**
 * Helper that adapts a typed component to a registration. Lets
 * callers write:
 *
 *   <ModalRoot registrations={makeRegistrations({
 *     BUG_REPORT: BugReportModalBody,
 *     LOGIN: LoginModalBody,
 *   })} />
 */
export function makeRegistrations<K extends ModalKind>(
  map: Partial<{
    [P in K]: ComponentType<{ modalProps: unknown; onClose: () => void }>;
  }>,
): ModalRegistrationMap {
  const out: ModalRegistrationMap = {};
  for (const [k, Comp] of Object.entries(map)) {
    if (!Comp) continue;
    out[k as K] = {
      render: (props) => <Comp modalProps={props} onClose={() => {}} />,
    };
  }
  return out;
}

import React, { useEffect, useState } from "react";
import { cn } from "@/lib/utils";

export interface ProfileCompletenessData {
  hasAvatar: boolean;
  hasBio: boolean;
  hasMajor: boolean;
  hasInterests: boolean;
}

export interface ProgressRingProps {
  /** Size of the SVG element in pixels (width and height) */
  size?: number;
  /** Stroke width of the ring track and fill */
  strokeWidth?: number;
  /** Current percentage (0 to 100). If omitted, calculated from profileData. */
  percentage?: number;
  /** User profile completion criteria */
  profileData?: ProfileCompletenessData;
  /** Child avatar component to wrap inside the progress ring */
  children?: React.ReactNode;
  /** Additional container className */
  className?: string;
  /** Custom stroke color class for completed ring fill */
  strokeColorClass?: string;
  /** Show step breakdown indicators or percentage label */
  showBadge?: boolean;
}

/**
 * Calculates completion percentage based on 4 key profile metrics:
 * Avatar (25%), Bio (25%), Major (25%), Interests (25%).
 */
export function calculateProfileCompleteness(data?: ProfileCompletenessData): number {
  if (!data) return 0;
  let score = 0;
  if (data.hasAvatar) score += 25;
  if (data.hasBio) score += 25;
  if (data.hasMajor) score += 25;
  if (data.hasInterests) score += 25;
  return score;
}

/**
 * Onboarding Progress Ring SVG animation component (#1971).
 * Wraps around user avatars and smoothly animates stroke-dashoffset on load/update.
 */
export const ProgressRing: React.FC<ProgressRingProps> = ({
  size = 120,
  strokeWidth = 6,
  percentage,
  profileData,
  children,
  className = "",
  strokeColorClass = "stroke-emerald-500 dark:stroke-emerald-400",
  showBadge = true,
}) => {
  const targetPercentage =
    percentage !== undefined ? percentage : calculateProfileCompleteness(profileData);

  const [animatedPercent, setAnimatedPercent] = useState(0);

  // Trigger smooth CSS animation from 0 to target on mount / update
  useEffect(() => {
    const timer = setTimeout(() => {
      setAnimatedPercent(Math.min(100, Math.max(0, targetPercentage)));
    }, 50);
    return () => clearTimeout(timer);
  }, [targetPercentage]);

  const center = size / 2;
  const radius = center - strokeWidth;
  const circumference = 2 * Math.PI * radius;
  const strokeDashoffset = circumference - (animatedPercent / 100) * circumference;

  return (
    <div
      className={cn("relative inline-flex items-center justify-center shrink-0", className)}
      style={{ width: size, height: size }}
    >
      {/* Animated SVG Progress Ring */}
      <svg
        width={size}
        height={size}
        viewBox={`0 0 ${size} ${size}`}
        className="absolute inset-0 h-full w-full -rotate-90 pointer-events-none"
        aria-hidden="true"
      >
        {/* Background Track */}
        <circle
          cx={center}
          cy={center}
          r={radius}
          fill="none"
          strokeWidth={strokeWidth}
          className="stroke-neutral-200 dark:stroke-neutral-800"
        />
        {/* Animated Progress Fill */}
        <circle
          cx={center}
          cy={center}
          r={radius}
          fill="none"
          strokeWidth={strokeWidth}
          strokeLinecap="round"
          strokeDasharray={circumference}
          strokeDashoffset={strokeDashoffset}
          className={cn(
            "transition-[stroke-dashoffset] duration-1000 ease-in-out",
            strokeColorClass,
          )}
        />
      </svg>

      {/* Embedded Child Avatar Container */}
      <div
        className="overflow-hidden rounded-full flex items-center justify-center"
        style={{
          width: size - strokeWidth * 3,
          height: size - strokeWidth * 3,
        }}
      >
        {children}
      </div>

      {/* Percentage Badge */}
      {showBadge && (
        <span
          className={cn(
            "absolute -bottom-1 right-0 rounded-full border-2 border-black px-1.5 py-0.5 font-mono text-[10px] font-bold text-black dark:border-cream dark:text-black",
            animatedPercent === 100 ? "bg-lime" : "bg-amber-300",
          )}
        >
          {animatedPercent}%
        </span>
      )}
    </div>
  );
};

