import React from "react";
import { SwipeToDismiss } from "@/components/ui/SwipeToDismiss";

interface NotificationItemProps {
  notification: {
    id: string;
    type: string;
    title: string;
    message: string;
    timestamp: string;
    isRead: boolean;
    link?: string;
    metadata?: Record<string, any> | null;
  };
  onMarkAsRead: (id: string) => void;
  /**
   * Called after a successful swipe-to-dismiss gesture. Parents should treat
   * this as the trigger for an optimistic delete (remove from local state /
   * cache immediately, then fire the deletion mutation).
   */
  onDelete?: (id: string) => void;
}

const NotificationItem: React.FC<NotificationItemProps> = ({
  notification,
  onMarkAsRead,
  onDelete,
}) => {
  const handleItemClick = () => {
    onMarkAsRead(notification.id);
    if (notification.link) {
      window.location.href = notification.link;
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      handleItemClick();
    }
  };

  const card = (
    <div
      onClick={handleItemClick}
      onKeyDown={handleKeyDown}
      role="button"
      tabIndex={0}
      aria-label={`${notification.isRead ? "Read" : "Unread"} notification: ${notification.title}`}
      className={`p-3 border-b border-gray-100 cursor-pointer transition-colors duration-200 hover:bg-gray-50 flex flex-col gap-1 text-left ${
        !notification.isRead ? "bg-blue-50/60 font-medium" : "bg-white"
      }`}
    >
      {" "}
      <div className="flex justify-between items-start gap-2">
        <span className="text-[10px] font-semibold uppercase tracking-wider text-gray-500">
          {notification.type}
        </span>
        <span className="text-[10px] text-gray-400">{notification.timestamp}</span>
      </div>
      <h4 className="text-sm text-gray-800 line-clamp-1">{notification.title}</h4>
      <p className="text-xs text-gray-500 line-clamp-2">{notification.message}</p>
      {!notification.isRead && <span className="w-2 h-2 bg-blue-600 rounded-full mt-1 self-end" />}
    </div>
  );

  if (!onDelete) return card;

  return (
    <SwipeToDismiss
      onDismiss={() => onDelete(notification.id)}
      ariaLabel={`Swipe to dismiss notification: ${notification.title}`}
    >
      {card}
    </SwipeToDismiss>
  );
};

export default NotificationItem;

import React, { useState, useMemo, useRef, forwardRef, useId } from "react";
import * as Popover from "@radix-ui/react-popover";
import { useVirtualizer } from "@tanstack/react-virtual";
import { Check, ChevronsUpDown, Search } from "lucide-react";
import { cn } from "@/lib/utils"; // Adjust path to your cn utility
import { Button } from "@/components/ui/button";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command"; // Assuming shadcn/ui command exists, or fallback to custom

export interface ComboboxOption {
  value: string;
  label: string;
  // Allow additional metadata if needed
  [key: string]: any;
}

interface ComboboxProps {
  options: ComboboxOption[];
  value?: string;
  onValueChange?: (value: string) => void;
  placeholder?: string;
  emptyStateMessage?: string;
  name?: string; // For React Hook Form integration
  disabled?: boolean;
  className?: string;
}

/**
 * Unified Accessible Combobox Component
 *
 * Features:
 * - Built on Radix UI Popover for absolute ARIA accessibility.
 * - Local filtering logic using `.includes()` (case-insensitive).
 * - Conditional Virtualization: Uses `@tanstack/react-virtual` if options.length > 100
 *   to prevent browser freezing from excessive DOM nodes.
 * - Seamless React Hook Form integration via `name` and `forwardRef`.
 * - Full keyboard navigation support (Arrow keys, Enter, Escape).
 */
export const Combobox = forwardRef<HTMLInputElement, ComboboxProps>(
  (
    {
      options,
      value,
      onValueChange,
      placeholder = "Select an option...",
      emptyStateMessage = "No matching options found.",
      name,
      disabled = false,
      className,
    },
    ref,
  ) => {
    const [open, setOpen] = useState(false);
    const [inputValue, setInputValue] = useState("");
    const componentId = useId();
    const listRef = useRef<HTMLDivElement>(null);

    // Filter options based on input value
    const filteredOptions = useMemo(() => {
      if (!inputValue) return options;
      const lowerQuery = inputValue.toLowerCase();
      return options.filter((option) => option.label.toLowerCase().includes(lowerQuery));
    }, [options, inputValue]);

    // Determine if we need virtualization (> 100 items)
    const shouldVirtualize = filteredOptions.length > 100;

    // Setup virtualizer only if needed
    const virtualizer = useVirtualizer({
      count: shouldVirtualize ? filteredOptions.length : 0,
      getScrollElement: () => listRef.current,
      estimateSize: () => 40, // Estimated height of each item in pixels
      overscan: 5,
    });

    const selectedOption = options.find((opt) => opt.value === value);

    const handleSelect = (currentValue: string) => {
      const newValue = currentValue === value ? "" : currentValue;
      onValueChange?.(newValue);
      setOpen(false);
      setInputValue(""); // Clear search on selection
    };

    return (
      <Popover.Root open={open} onOpenChange={setOpen}>
        <Popover.Trigger asChild>
          <Button
            variant="outline"
            role="combobox"
            aria-expanded={open}
            aria-controls={componentId}
            aria-haspopup="listbox"
            disabled={disabled}
            className={cn(
              "w-full justify-between font-normal",
              !value && "text-muted-foreground",
              className,
            )}
          >
            <span className="truncate">{selectedOption ? selectedOption.label : placeholder}</span>
            <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
          </Button>
        </Popover.Trigger>

        <Popover.Portal>
          <Popover.Content
            className="z-50 w-[--radix-popover-trigger-width] rounded-md border bg-popover p-0 text-popover-foreground shadow-md outline-none data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2"
            align="start"
            sideOffset={4}
          >
            <Command className="bg-transparent">
              <div className="flex items-center border-b px-3" cmdk-input-wrapper="">
                <Search className="mr-2 h-4 w-4 shrink-0 opacity-50" />
                <CommandInput
                  ref={ref}
                  name={name}
