describe("GraphQL Auth Directive", () => {
  it("Unauthenticated request should return Unauthorized", async () => {
    const response = await yoga.fetch("http://localhost:4000/api/graphql", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ query: "query { allUsers { id } }" }),
    });
    const json = await response.json();
    expect(json.errors[0].message).toBe("Not authenticated");
    expect(json.errors[0].extensions.code).toBe("UNAUTHENTICATED");
  });

  it("Authenticated USER should be rejected from ADMIN field", async () => {
    vi.mocked(supabase.auth.getUser).mockResolvedValue({
      data: { user: { id: "user-123" } },
    } as any);
    vi.mocked(supabase.from).mockReturnValue({
      select: () => ({
        eq: () => ({
          single: async () => ({ data: { role: "USER" }, error: null }),
        }),
      }),
    } as any);

    const response = await yoga.fetch("http://localhost:4000/api/graphql", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: "Bearer token-user",
      },
      body: JSON.stringify({ query: "query { allUsers { id } }" }),
    });
    const json = await response.json();
    expect(json.errors[0].message).toBe("Not authorized");
    expect(json.errors[0].extensions.code).toBe("UNAUTHORIZED");
  });

  it("Authenticated ADMIN should receive data", async () => {
    vi.mocked(supabase.auth.getUser).mockResolvedValue({
      data: { user: { id: "admin-123" } },
    } as any);

    vi.mocked(supabase.from).mockImplementation((table: string) => {
      if (table === "profiles") {
        return {
          select: () => {
            const queryObj = Promise.resolve({
              data: [{ id: "user-123" }, { id: "admin-123" }],
              error: null,
            });
            (queryObj as any).eq = () => ({
              single: async () => ({ data: { role: "ADMIN" }, error: null }),
            });
            return queryObj;
          },
        } as any;
      }
      return {} as any;
    });

    const response = await yoga.fetch("http://localhost:4000/api/graphql", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: "Bearer token-admin",
      },
      body: JSON.stringify({ query: "query { allUsers { id } }" }),
    });
    const json = await response.json();
    expect(json.data.allUsers).toBeDefined();
    expect(json.data.allUsers.length).toBe(2);
  });

  it("Ensure existing queries continue working (clubs)", async () => {
    vi.mocked(supabase.from).mockImplementation((table: string) => {
      if (table === "clubs") {
        return {
          select: () => Promise.resolve({ data: [{ id: "club-1", name: "Club 1" }], error: null }),
        } as any;
      }
      return {} as any;
    });

    const response = await yoga.fetch("http://localhost:4000/api/graphql", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ query: "query { clubs { id name } }" }),
    });
    const json = await response.json();
    expect(json.data.clubs).toBeDefined();
    expect(json.data.clubs[0].id).toBe("club-1");
  });
});

import { useState, useCallback } from "react";
import { generateIdempotencyKey, hashPayload } from "@/lib/idempotency";
import { supabase } from "@/lib/supabaseClient"; // Adjust path to your actual supabase client
import { toast } from "sonner";

interface PaymentPayload {
  eventId: string;
  quantity: number;
  amount: number;
  // Add other relevant payment fields
}

interface UseIdempotentPaymentReturn {
  processPayment: (payload: PaymentPayload) => Promise<void>;
  isProcessing: boolean;
  error: string | null;
}

/**
 * Custom hook to handle idempotent payment processing.
 * Generates a unique key per checkout session and ensures the backend
 * processes the payment exactly once, even on network retries.
 */
export function useIdempotentPayment(): UseIdempotentPaymentReturn {
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const processPayment = useCallback(
    async (payload: PaymentPayload) => {
      if (isProcessing) {
        console.warn("Payment already in progress, ignoring duplicate call.");
        return;
      }

      setIsProcessing(true);
      setError(null);

      try {
        // 1. Generate a unique idempotency key for this specific checkout attempt
        const idempotencyKey = generateIdempotencyKey();

        // 2. Hash the payload to ensure integrity
        const payloadHash = await hashPayload(payload);

        // 3. Call the Supabase Edge Function with the idempotency key in headers
        const { data, error: fnError } = await supabase.functions.invoke("process-payment", {
          body: payload,
          headers: {
            "Idempotency-Key": idempotencyKey,
            "X-Payload-Hash": payloadHash,
          },
        });

        if (fnError) {
          // Handle 409 Conflict specifically (already processing)
          if (fnError.message?.includes("409") || fnError.message?.includes("Conflict")) {
            toast.info("Payment is already being processed. Please wait.");
            return;
          }
          throw new Error(fnError.message || "Payment processing failed");
        }

        toast.success("Payment processed successfully!");
        return data;
      } catch (err: any) {
        const errorMessage = err.message || "An unexpected error occurred during payment.";
        setError(errorMessage);
        toast.error(errorMessage);
        throw err;
      } finally {
        setIsProcessing(false);
      }
    },
    [isProcessing],
  );

  return { processPayment, isProcessing, error };
}

