            event_date: new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString(),
            location: "Art Studio 3",
            clubs: { name: "Art & Design" },
            event_rsvps: [],
            saved_events: [],
          },
          {
            id: "mock-3",
